# The app window (MessiahApp.exe, compiled from app\Messiah.App): its own test (--test) builds every page and the chat
# from a home folder's files and prints them - here a sandbox home: a new install, one with made-up data, and every
# state file filled with garbage (in a profile path with spaces and non-English letters). No window opens; nothing is
# read from this PC's own .claude. (tray-windows and chaos-state check it too.)
. "$PSScriptRoot\..\lib.ps1"
if (-not $AppExe) { Skip 'app' 'not built here (tools\app\build.ps1)'; Finish }
function Run-App([string]$Home_, [hashtable]$Env = @{}, [string[]]$ArgList = @()) { Invoke-App $Home_ $ArgList $Env }
function Errs($r) { ((@($r.Out -split "`r?`n" | Where-Object { $_ -match 'PAGE ERROR' }) + @($r.Err.Trim()) | Where-Object { $_ }) -join ' | ') }
$pages = 'Welcome', 'Home', 'Status', 'Activity/Checks', 'Activity/Stability', 'Activity/Trends', 'Activity/Performance', 'Activity/Storage', 'Activity/Alerts', 'Settings/General', 'Settings/Windows', 'Settings/Tools'

Section 'a new install (nothing written yet)'
$H = "$Work\new"; New-Item "$H\.claude", "$H\Documents" -ItemType Directory -Force | Out-Null
$r = Run-App $H
Check 'it runs and ends by itself' ($r.Code -eq 0) "exit $($r.Code) $($r.Err)"
Check 'Restart into an update keeps what the copy is (--live, --tray), not its page - the tray stays the tray (10/22: it lost --live)' ($r.Out -match '(?m)^RESTART ARGS: --live --tray --after 42 / --live --after 7\s*$') ''
$miss = @($pages | Where-Object { $r.Out -notmatch "(?m)^PAGE: $([regex]::Escape($_)) " })
Check 'every page is built' (-not $miss) "missing: $($miss -join ', ')"
Check 'no page fails' (-not (Errs $r)) (Errs $r)
Check 'Home, this week on a new install: the card anyway - not checked yet, and that it fills in during the first week (10/26)' ($r.Out -match 'CARD: This week\s+Crashes: None\s+Maintenance: Not checked yet - the first check runs in the background after login\s+Your first week with Messiah - .+ A full week from \w') (($r.Out -split "`n" | Select-String -Pattern 'This week' -Context 0, 4) -join ' / ')
Check "Home's Next tile on a new install: the first check, not 'App updates - due now' (10/26)" ($r.Out -match 'TILE: Next: First check / In the background after login') (($r.Out -split "`n" | Select-String -Pattern 'TILE: Next') -join ' / ')
Check "... Next once checked: the soonest check (not the first line, never the weekly Self-test - 10/27), a due one first, a fallback with none" ($r.Out -match "(?m)^NEXT: First check / In the background after login \| Cleanup / $([regex]::Escape((Get-Date).AddDays(2).ToString('MMM d'))) \| Dust reminder / Runs at the next check \| At login / And every 4 hours \| At login / And every 4 hours\s*$") (($r.Out -split "`n" | Select-String -Pattern '^NEXT:') -join '')
Check "Trends' Free space on C:: a mark at each drop of 20 GB or more, naming the game installed then (a folder made between the checks, at least half the drop) (10/27)" ($r.Out -match '(?m)^FREEDROPS: 10-03 90 GB less free - Call of Duty installed \| 10-05 30 GB less free\s*$') (($r.Out -split "`n" | Select-String -Pattern '^FREEDROPS:') -join '')
Check "Trends' Free space on C:: the line beside the number names the marked drop that is most of the fall - its day and why (10/28: the amber mark said nothing until pointed at)" ($r.Out -match '(?m)^DRIFTSINCE: down 130 GB since Oct 1, most of it on Oct 3 \(Call of Duty installed\) \| down 130 GB since Oct 1, most of it on Oct 3 \| down 50 GB since Oct 1 \| up 50 GB since Oct 1\s*$') ([regex]::Match($r.Out, '(?m)^DRIFTSINCE:.*').Value)
Check "Home's Last game tile says when the session was and opens that game's card on Performance - not Trends, which has no games (10/27); 'last session' and its day together (10/28)" ($r.Out -match '(?m)^LASTGAME: 199 fps / Call of Duty, last session yesterday, 1% low 149 -> Activity/Performance#Call of Duty \| Nothing yet / Measured while you play -> Activity/Performance\s*$') (($r.Out -split "`n" | Select-String -Pattern '^LASTGAME:') -join '')
Check "Home's Last game tile ends with the game's verdict in a few words, the 1% low only without one; Home's Last session card says the whole verdict when its last minute is the game's latest (Game check-up, 10/28)" ($r.Out -match '(?m)^LASTVERDICT: NBA 2K20, last session yesterday, capped at 60 fps \| Call of Duty, last session yesterday, held back by the processor \| Call of Duty, last session yesterday, 1% low 110 \| session: Held back by the processor or the game \(graphics card 48% busy\): 150 fps on a 240 Hz screen\. \| old: 1\s*$') (($r.Out -split "`n" | Select-String -Pattern '^LASTVERDICT:') -join '')
Check "Home's Free space on C: tile: the last check's number, else the storage scan's system drive, else C: read now - not a bare '-' before the first check (10/27)" ($r.Out -match '(?m)^FREEC: 80 \| 120 \| 42 \| none \| read now\s*$' -and $r.Out -match 'TILE: Free space on C:: \d+ GB') (($r.Out -split "`n" | Select-String -Pattern '^FREEC:|TILE: Free') -join '')
Check "Home's tiles open the card they sum up - Free space Storage's Drives, Next Checks' Scheduled checks - through Open (a tile's '#card' went nowhere, 10/27)" (($r.Out -match '(?m)^\s+GO: Activity/Storage#Drives \(Open Games > Storage\)\s*$') -and ($r.Out -match '(?m)^\s+GO: Activity/Checks#Scheduled checks \(Open Health > Checks\)\s*$') -and ($r.Out -match '(?m)^\s+GO: Activity/Performance(#.+)? \(Open Games > Performance\)\s*$') -and ($r.Out -match '(?m)^CARD: Scheduled checks\s*$')) (($r.Out -split "`n" | Where-Object { $_ -match '^\s+GO: Activity/(Storage|Checks|Performance)' }) -join ' / ')
Check "Home's Claude card: 'Close chat' while the chat is open, 'Open chat' (accent) again after - it said 'Open chat' beside the open chat (10/27)" ($r.Out -match '(?m)^CHATBTN: Open chat \(accent\) \| Close chat \| Open chat \(accent\) \| closed again True\s*$') (($r.Out -split "`n" | Select-String -Pattern '^CHATBTN:') -join '')
Check "Checks' Scheduled checks say when like Home (10/26: 'Oct 27, 2026' there, 'Tomorrow' here); a far date keeps its year; 'After the first check' on a new install" ($r.Out -match "(?m)^SCHEDWHEN: Tomorrow \| $([regex]::Escape((Get-Date).AddDays(40).ToString('MMM d')))  \(every 3 months, compared with day one\) \| year kept \| Runs at the next check  \(every 6 months\) \| After the first check\s*$") (($r.Out -split "`n" | Select-String -Pattern '^SCHEDWHEN:') -join '')
Check "Checks' Last background check says 'took about a minute' past 59 s, the seconds under one (10/28: 'took 64 s')" ($r.Out -match '(?m)^TOOK: Done \(took 48 s\) \| Done \(took about a minute\) \| Done \(took about 2 minutes\) \| Done \(took about 2 minutes\) \| Done \(took about 10 minutes\)\s*$') (($r.Out -split "`n" | Select-String -Pattern '^TOOK:') -join '')
$dn = { param($n) $d = (Get-Date).Date.AddDays(-$n); $d.ToString($(if ($d.Year -eq (Get-Date).Year) { 'dddd, MMM d' } else { 'dddd, MMM d, yyyy' })) }
Check "What maintenance did's day headings all say the weekday, the year only when it isn't this one (10/28: 'Sunday, Oct 25' above a bare 'Oct 8')" ($r.Out -match ('(?m)^DAYNAME: ' + [regex]::Escape("Today | Yesterday | $(& $dn 3) | $(& $dn 20) | $(& $dn 400)") + '\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^DAYNAME:') -join '')
$wy = { param($n) $d = (Get-Date).Date.AddDays(-$n); $d.ToString($(if ($d.Year -eq (Get-Date).Year) { 'MMM d' } else { 'MMM d, yyyy' })) }
Check "Dates this week give the date too (10/28: 'Last backup Mon 12:00 PM'); over a week old name the year when it isn't this one - Stability's oldest events, alerts, reports (10/28: last year's blue screen read 'Oct 8')" ($r.Out -match ('(?m)^WHENYEAR: ' + [regex]::Escape("$((Get-Date).Date.AddDays(-3).AddHours(9).ToString('ddd MMM d h:mm tt')) | $(& $wy 20) | $(& $wy 400)") + '\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^WHENYEAR:') -join '')
$vexp = 'Smooth: Smooth: 236 fps on a 239 Hz screen | Capped: Capped at 60 fps on a 239 Hz screen | Capped: Capped at 60 fps on a 239 Hz screen | Processor: Held back by the processor or the game (graphics card 55% busy): 172 fps on a 239 Hz screen | Graphics: Held back by the graphics card (97% busy): 172 fps on a 239 Hz screen | Paced: Runs well: 172 fps on a 239 Hz screen, 1% low 120, paced by the processor or the game (graphics card 80% busy) | Stuttery: More hitches than usual: 21 in the last minute measured, usually about 1 | Capped: Capped at 60 fps on a 239 Hz screen | none | none'
Check "Game check-up: a verdict for every game's latest session (10/28) - smooth near the screen's rate, capped (flat second by second, or a common cap without the seconds; 58.5 says 60), held back by the processor or the graphics card, more hitches than the game's own usual (5+ more - NBA 2K20's 5 vs 2 isn't), none under 1000 frames or no sessions" ($r.Out -match ('(?m)^VERDICT: ' + [regex]::Escape($vexp) + '\s*$')) ([regex]::Match($r.Out, '(?m)^VERDICT:.*').Value)
$lexp = 'none | Steady at its frame cap (about 60 fps) - nothing is holding it back. | The processor or the game is the limit (the graphics card is busy only 80% of each frame) - graphics settings won''t raise it; faster RAM (EXPO) and fewer background apps do. | The graphics card is the limit (busy 97% of each frame) - lower graphics settings or DLSS raise the frame rate.'
Check "Game check-up: the limit line under a verdict agrees with it - nothing at the screen's rate (even 97% busy), the cap, 70-89% busy is the processor's pace (10/28: 'Smooth' above 'the processor is the limit')" ($r.Out -match ('(?m)^LIMITAGREE: ' + [regex]::Escape($lexp) + '\s*$')) ([regex]::Match($r.Out, '(?m)^LIMITAGREE:.*').Value)
$sexp = 'Nothing else holds it back. | Graphics settings won''t raise it; faster RAM (EXPO) and fewer background apps do. | Lower graphics settings or DLSS raise the frame rate. | Graphics settings won''t raise it; faster RAM (EXPO) and fewer background apps do. | Steady at its frame cap (about 60 fps) - nothing is holding it back.'
Check "Game check-up: under the latest session's verdict the limit line keeps only the advice - the verdict already says the cap or the busy % (10/28: '48% busy' twice; Paced's '72%' too); a minute too short for a verdict keeps the whole reading" ($r.Out -match ('(?m)^LIMITSAID: ' + [regex]::Escape($sexp) + '\s*$')) ([regex]::Match($r.Out, '(?m)^LIMITSAID:.*').Value)
$capOwn = 'Most likely the game''s own frame limit, or the game set to 60 Hz. In its video settings, set the frame rate limit to Unlimited and the refresh rate to 239 Hz.'; $capNv = ' Messiah''s NVIDIA settings keep it just under the screen''s rate.'; $capHalf = 'Half the screen''s rate usually means V-Sync at half rate in the game.'
$cexp = "$capOwn$capNv | $capOwn | $capHalf Turn V-Sync off in its video settings: G-SYNC keeps it smooth without it. | $capHalf In its video settings, set V-Sync to full rate. | Usually the game's own frame limit or V-Sync. Both are in the game's video settings. | none | $($capOwn -replace ', or the game set to 60 Hz', '')$capNv"
Check "Game check-up: a capped game says where the cap probably comes from and what to set in the game (10/28) - the game's own limit (or a 60 Hz mode; not for an odd 172), V-Sync at half the screen's rate, G-SYNC's words only when it's on; nothing for a game at the screen's rate" ($r.Out -match ('(?m)^CAPCAUSE: ' + [regex]::Escape($cexp) + '\s*$')) ([regex]::Match($r.Out, '(?m)^CAPCAUSE:.*').Value)
$d3 = (Get-Date).Date.AddDays(-3)
$want = "$($d3.AddHours(7).ToString('MMM d, h:mm tt')) .. $($d3.AddHours(19.5).ToString('h:mm tt')) | $($d3.ToString('MMM d')) .. $((Get-Date).ToString('MMM d'))"
Check "A chart whose sessions were all on one day says the times at its ends, not 'Oct 25 ... Oct 25' (10/28)" ($r.Out -match ('(?m)^ENDS: ' + [regex]::Escape($want) + '\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^ENDS:') -join '')
Check "No second-by-second view: said once, under the first game card missing it; before Oct 21 'kept only the totals', later 'kept only its totals' (10/28: under every game)" ($r.Out -match '(?m)^SECNOTE: b \| The second-by-second view shows from the next session on \(sessions measured before Oct 21 kept only the totals\)\. \| This session kept only its totals - the second-by-second view shows again from the next session on\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SECNOTE:') -join '')
$st = { param($n, $t) $d = (Get-Date).Date.AddDays(-$n).AddHours(3); $d.ToString($(if ($d.Year -eq (Get-Date).Year) { 'ddd MMM d' } else { 'ddd MMM d, yyyy' })) + $(if ($t) { $d.ToString(', h:mm tt') } else { '' }) }
$want = "$(& $st 3 $true) | $(& $st 400 $true) | $((Get-Date).Date.AddDays(-400).ToString($(if ((Get-Date).Date.AddDays(-400).Year -eq (Get-Date).Year) { 'ddd MMM d' } else { 'ddd MMM d, yyyy' })))"
Check "Chart tooltips and marks name the year when it isn't this one - Stability's 120 days cross New Year in January (10/28)" ($r.Out -match ('(?m)^STAMP: ' + [regex]::Escape($want) + '\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^STAMP:') -join '')
Check "Checks' Scheduled checks come soonest first - due, the next login, then by date; one without a date last (10/28: Self-check Nov 1 sat under a tune-up next September)" ($r.Out -match '(?m)^SCHEDORDER: Benchmark, Self-check, App updates, Cleanup, Full tune-up, Notes\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SCHEDORDER:') -join '')
Check "Checks' Scheduled checks footer says when restart-only work finishes by Restart at night (10/28: always 'the next time you turn the PC off')" (($r.Out -match '(?m)^SCHEDFOOT: .*finishes with a restart at night while the PC is unused \(Settings > Restart at night\)\. \| .*finishes the next time you turn the PC off or restart\.\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^SCHEDFOOT:') -join '')
Check "The restart-pending card says when the work finishes by Restart at night, as the Checks footer does (10/28: always 'the next time you turn the PC off')" (($r.Out -match '(?m)^RESTARTCARD: These finish by themselves at the next restart: one at night while the PC is unused \(Settings > Restart at night\), or when you turn it off\. The check after that confirms it\. \| These finish by themselves the next time you turn the PC off or restart\. The check after that confirms it\.\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^RESTARTCARD:') -join '')
$fl = ($r.Out -split "`r?`n" | Where-Object { $_ -match '^\s*FILTERS: ' }) -join ''
Check 'Optimizations before the first check: its own Not checked filter, not counted as Off (10/26: "Off 27"); no Put back yet' ($fl -match 'All\s+(\d+)\*? \| .*Not checked\s+(\d+) \| Off\s+(\d+)' -and [int]$Matches[2] -gt 0 -and [int]$Matches[3] -lt [int]$Matches[2] -and $fl -notmatch "Put back") $fl
Check 'tabs: Home, Games, Health, Optimizations, Settings (10/25: five, each with one job)' ($r.Out -match '(?m)^NAV: Home \| Games \| Health \| Optimizations \| Settings\s*$') ''
Check 'keys: Ctrl+1..5 open the tabs, Ctrl+Tab / Ctrl+Shift+Tab go round a tab''s pages, the tooltips say so (10/26)' ($r.Out -match '(?m)^KEYS: Activity/Stability > Activity/Checks > Activity/Trends > Activity/Alerts > Home > False \| tips: Home \(Ctrl\+1\) \| Games \(Ctrl\+2\) - Ctrl\+Tab for its next page \|.* Settings \(Ctrl\+5\) - ') (($r.Out -split "`n" | Where-Object { $_ -match '^KEYS:' }) -join '')
Check 'app update names as people say them: "Valve.Steam" -> "Steam", a version''s numbers kept with dots (10/26)' ($r.Out -match '(?m)^APPNAMES: Steam \| Discord \| Windows Terminal \| Node\.js \| Windows App Runtime 1\.8 \| Visual C\+\+ Redistributable 2013 x64 \| Chrome \| Microsoft msodbcsql 17 \| Python 3\.12\r?$') (($r.Out -split "`n" | Where-Object { $_ -match '^APPNAMES:' }) -join '')
Check 'a row''s page: Shell.Open goes to the page of "Page/Sub#Card" (10/26)' ($r.Out -match '(?m)^OPEN: Activity/Performance > Activity/Checks > Activity/Stability\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^OPEN:' }) -join '')
$gen = if ($r.Out -match '(?s)PAGE: Settings/General(.*?)PAGE: Settings/Windows') { $Matches[1] } else { '' }
Check 'keys: Ctrl+/ opens Settings > General''s Keyboard shortcuts card, which lists them (chat keys only with the AI assistant) (10/26)' (($r.Out -match '(?m)^SHORTCUTS: Settings/General \| Ctrl\+K, Ctrl\+Alt\+M, Ctrl\+1 to 5, Ctrl\+Tab, Ctrl\+/, Ctrl\+T, Ctrl\+W, In the chat \| no AI: 5\s*$') -and $gen -match 'Keyboard shortcuts' -and $gen -match 'Ctrl\+/') (($r.Out -split "`n" | Where-Object { $_ -match '^SHORTCUTS:' }) -join '')
Check 'keys: the shortcuts read as sentences, no semicolon or dash join - Ctrl+K''s ''Search Messiah, or Ctrl+F outside the chat. Esc closes it'' (10/28)' ($r.Out -match '(?m)^KEYWORDS: 0 of 8 join with a semicolon or dash \| Search Messiah, or Ctrl\+F outside the chat\. Esc closes it\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^KEYWORDS:' }) -join '')
Check 'here: the card Shell.Open lands on flashes its border in the accent (a group: each setting''s card) (10/26)' ($r.Out -match '(?m)^FLASH: card 1 accent True \| group [1-9]\d*\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^FLASH:' }) -join '')
Check 'start-up: the data is timed part by part (the status and the checks too), and the driver / BIOS read is one part that the window never waits for (10/26: 650 of 950 ms), as are the monitors and tasks (140 of the checks'' 210)' ($r.Out -match '(?m)^DATA: read in \d+ ms \(status \d+ \(state \d+, claude \d+, .*scheduled \d+\), checks \d+ \(files \d+, .*live \d+, .*tasks \d+\), .*hardware \d+, .*sig \d+\)') (($r.Out -split "`n" | Where-Object { $_ -match '^DATA:' }) -join '')
Check 'Claude Code''s version comes from the exe''s version stamp (no process - 36 ms of the start, 10/26); the test stand-in has none, so it still asks --version' ($r.Out -match '(?m)^CLAUDEVER: (\d+\.\d+\.\d+ from --version|\s*from\s*)\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^CLAUDEVER:' }) -join '')
Check 'the last driver / BIOS read is kept in hardware.json and read back the same, so a cold start''s Tools page has them at once (10/27)' ($r.Out -match '(?m)^HWCACHE: NVIDIA GeForce RTX 5070 32\.0\.15\.8157 2026-09-30 \| ASUSTeK ROG STRIX B650 3602 2026-08-01 s \| empty none\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^HWCACHE:' }) -join '')
Check "Tools' graphics driver shows NVIDIA's own number (10/27: 'driver 32.0.15.6094' -> 560.94); AMD and odd versions stay as Windows says them" ($r.Out -match '(?m)^DRIVERVER: 560\.94 \| 536\.99 \| 32\.0\.21042\.62 \| 441\.20 \| beta \| \s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^DRIVERVER:' }) -join '')
Check "a switch that is one In place row by itself has the same name on Optimizations' Choose and In place (10/27: 'Remove Edge completely' / 'Edge removed completely', 4 more)" ($r.Out -match '(?m)^SWITCHNAMES: (1\d|[5-9]) one-switch rows, same names\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SWITCHNAMES') -join ' / ')
Check "a row that is only its switch's section reads like the switch, and a row holding another switch names it (10/27: Hibernation off inside 'Best power plan, USB sleep off'; 'Razer and Logitech auto-installers blocked'), and every Choose switch has an In place row (10/27: Xbox Game Bar removed and SysMain off had none)" ($r.Out -match '(?m)^SWITCHROWS: [1-9]\d* rows with another switch inside, each named\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SWITCHROWS') -join ' / ')
Check "each Choose switch's one line says what it does, not only what turning it off means (10/27: OneDrive's read 'Off: OneDrive comes back and can sync again.')" ($r.Out -match '(?m)^SWITCHLINES: [1-9]\d* switches, each says what it does\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SWITCHLINES') -join ' / ')
Check "a page name at the very start of a text links whole and draws as wide as the plain words (10/28: PAGELINKS read the link as ' > Status')" ($r.Out -match "(?m)^LINKSTART: link 'Optimizations > In place' \+ run ' names each setting\.' \| text 'Optimizations > In place names each setting\.' \| (\d+) of \1 px\s*$") (($r.Out -split "`n" | Select-String -Pattern '^LINKSTART') -join ' / ')
Check "a switch's one line never stops inside brackets (10/28: the temperature switch's line ended '... at idle (Games > Performance:')" ($r.Out -match '(?m)^SUBLINEBRACKETS: sample whole \| no switch stops inside\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SUBLINEBRACKETS') -join ' / ')
Check "Optimizations' Edge removed completely: whole sentences, no dashes (10/28: 'WebView2 - the part apps ... need -' / 'stays.' broke at a dash at 1366)" ($r.Out -match '(?m)^\s+Off unless you turn it on\. Uninstalls the Edge browser for good\.\s*$' -and $r.Out -notmatch 'WebView2 - ') ''
Check "Optimizations' Old Windows parts and Razer and Logitech: a short first sentence (10/28: 'about 7' / 'GB' split at 1366, Razer's More alone on a line)" ($r.Out -match '(?m)^\s+Frees about 7 GB and removes Windows parts nobody uses now\.\s*$' -and $r.Out -match "(?m)^\s+Plugging in their mice or headsets no longer installs Razer Synapse or Logitech's assistant\.\s*$") ''
Check "Optimizations' Mouse acceleration, SysMain, All app notifications and File Explorer: no ' - ' joining two thoughts mid-line (10/28)" ($r.Out -match '(?m)^\s+The same hand movement always moves the cursor the same distance, for better aim\.\s*$' -and $r.Out -match '(?m)^\s+Every folder opens the same way, so big folders open faster\.\s*$' -and $r.Out -notmatch 'SSD - Windows|mail\) - Windows|layout - big folders|distance - better') ''
Check "a switch tweaks.ps1 keeps on purpose says so on In place (10/27: 'Xbox Game Bar removed' read In place on a dual-CCD X3D; SysMain off on a hard drive)" ($r.Out -match '(?m)^KEPTROWS: x3d game-bar Kept - your processor needs it \| x3d sysmain - \| hdd sysmain Kept - Windows is on a hard drive \| plain -\s*$') (($r.Out -split "`n" | Select-String -Pattern '^KEPTROWS') -join ' / ')
Check "In place's headline doesn't count a kept-on-purpose row as in place (10/27: 'All 31 in place' with the Game Bar kept on a dual-CCD X3D)" ($r.Out -match '(?m)^KEPTHEAD: All 2 in place, 1 kept for this PC \| All 2 in place\s*$') (($r.Out -split "`n" | Select-String -Pattern '^KEPTHEAD') -join ' / ')
Check "Stability's Power-offs tile names only the kinds there are (10/27: '1 by you, 0 froze, 1 not answered'; 'Not sure' wasn't counted)" ($r.Out -match '(?m)^OFFSUB: 1 by you, 1 not answered \| 1 went off by itself, 2 not sure, 1 to answer on Home \| None recorded\s*$') (($r.Out -split "`n" | Select-String -Pattern '^OFFSUB') -join ' / ')
Check "Stability's Blue screens tile names the stop code (10/28: 'Each with a crash dump' with none)" ($r.Out -match '(?m)^BSODSUB: None recorded \| Stop code 0x109 \| Stop code 0x109 each time \| 2 different stop codes \| Stop code not recorded\s*$') (($r.Out -split "`n" | Select-String -Pattern '^BSODSUB') -join ' / ')
Check "Settings' backup card says when the next backup is made (10/28: with none it said 'at the next weekly maintenance' - it's the next check)" ($r.Out -match '(?m)^BACKUPWHEN: No backup yet - the first one is made at the next check \(or click Back up now\)\. \| The next one is made at the first check after \w{3} \w{3} \d+\. \| The next one is made at the next check\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^BACKUPWHEN') -join ' / ')
Check "Settings' backup card's last backup and what's in it read in the app's words (10/28: 'Weekly:wallpaper, ... colours', a full C:\Users\... path)" ($r.Out -match '(?m)^BACKUPLAST: Last backup yesterday 4:00 AM, in Documents\\PC Setup Kit Backup \| Last backup yesterday 12:00 AM, in D:\\PC Setup Kit Backup \| Every week: your wallpaper\s*$') (($r.Out -split "`n" | Select-String -Pattern '^BACKUPLAST') -join ' / ')
Check "a made-up home without a backup finds none - not the real PC's (10/28: it read the real Documents)" ($r.Out -match '(?m)^BACKUPFOUND: made-up home \| none\s*$') ([regex]::Match($r.Out, '(?m)^BACKUPFOUND:.*').Value)
$HB = "$Work\backup"; New-Item "$HB\.claude", "$HB\Documents\PC Setup Kit Backup" -ItemType Directory -Force | Out-Null
$zb = "$HB\Documents\PC Setup Kit Backup\PC-2026-10-01.zip"; [IO.File]::WriteAllBytes($zb, [byte[]](@(80, 75, 5, 6) + @(0) * 18)); (Get-Item $zb).LastWriteTime = (Get-Date).Date.AddDays(-1).AddHours(4)
$rb = Run-App $HB
Check "the backup card finds a made-up home's own backup in its Documents (10/28: the demo could never show one)" ($rb.Out -match '(?m)^BACKUPFOUND: made-up home \| Last backup yesterday 4:00 AM, in Documents\\PC Setup Kit Backup\s*$') ([regex]::Match($rb.Out, '(?m)^BACKUPFOUND:.*').Value)
Check "Checks' 'All fine' says what the background check looked at, from its report (10/28: it was a bare tick)" ($r.Out -match '(?m)^LOOKED: Looked at drivers, Claude Code, crashes, your tweaks, app updates and game saves\. \| \|\s*$') ([regex]::Match($r.Out, '(?m)^LOOKED:.*').Value)
Check "Storage's footer says when it was scanned (10/28: it read 'Looked today 12:11 AM' - other pages say Checked)" ($r.Out -match '(?m)^SCANNED: Scanned today \d+:\d\d [AP]M - once a day\. .+ \| Not scanned yet - once a day\. ') (($r.Out -split "`n" | Select-String -Pattern '^SCANNED') -join ' / ')
Check "A game's chart legend names Messiah's own tries, and Before and after doesn't say nothing changed under them (10/27)" ($r.Out -match "(?m)^MARKNOTE: A dashed mark: Messiah switched a setting it's trying there \(Tuned by measuring, above\)\. \| A dashed mark: something changed there \(a driver, Windows, the RAM speed, your settings\)\. \| A dashed mark: something changed there \(a driver, Windows, the RAM speed, your settings\), or Messiah switched a setting it's trying \(Tuned by measuring, above\)\. \| Nothing else changed between sessions yet - the dashed marks are Messiah's own tries") (($r.Out -split "`n" | Select-String -Pattern '^MARKNOTE') -join ' / ')
Check "Stability's first tile says what the last crash was in the Power-offs tile's words (10/27: 'Went off - you weren't sure', an unanswered one didn't say where to answer)" ($r.Out -match '(?m)^LASTCRASH: Blue screen 0x109 \| Went off by itself \| Went off - not sure why \| Went off - answer it on Home \| Went off - not answered\s*$') (($r.Out -split "`n" | Select-String -Pattern '^LASTCRASH') -join ' / ')
Check "Home's This week values start with a capital like its others (10/28: 'graphics card 73 °C', 'ping 23 ms while playing')" ($r.Out -match '(?m)^WEEKCAPS: Graphics card 73 °C \(normal\), processor 61 °C \(normal\) \| Processor 61 °C \(normal\) \| Ping 23 ms while playing, no lag\s*$') (($r.Out -split "`n" | Select-String -Pattern '^WEEKCAPS') -join ' / ')
Check "Home's This week counts a driver only by its install line (10/28: one NVIDIA update read '2 drivers' - the 'installed; no NVIDIA app recommendation' check line counted too)" ($r.Out -match '(?m)^WEEKDRIVERS: 1 driver \| Nothing needed doing \| 3 drivers\s*$') (($r.Out -split "`n" | Select-String -Pattern '^WEEKDRIVERS') -join ' / ')
Check "Home's This week Hottest says normal / warm / hot by Heat and wear's limits, and hot when the card slowed itself down (10/28: '73 °C' alone)" ($r.Out -match '(?m)^WEEKHEAT: Graphics card 79 °C \(warm\), processor 80 °C \(normal\) \| Graphics card 86 °C \(hot\), processor 81 °C \(warm\) \| Graphics card 70 °C \(hot - it slowed itself down\) \| Processor 90 °C \(hot\)\s*$') (($r.Out -split "`n" | Select-String -Pattern '^WEEKHEAT') -join ' / ')
Check "--audit's DASH check finds a line that breaks right after ' -' (the Edge switch's old line), not the same words without the dash or a line that doesn't wrap (10/28: both cases were found by eye)" ($r.Out -match '(?m)^DASHEND: .*game launchers need - \| stays\. \| none \| none\s*$') (($r.Out -split "`n" | Select-String -Pattern '^DASHEND') -join ' / ')
Check "--audit's DASH check also measures text made of several Runs (a bold start and the rest, like Ui.Rows' values) (10/28: only one-Run texts were checked)" ($r.Out -match '(?m)^DASHRUNS: .*game launchers need - \| stays\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^DASHRUNS') -join ' / ')
Check "A setting's 'More' link wraps with the line's last word, never alone on a line of its own, and --audit's LONEMORE check finds one that does (10/28: Show technical names at 1366)" ($r.Out -match '(?m)^LONEMORE: plain lone \(2 lines\) \| no-break not lone \(2 lines\)\s*$') (($r.Out -split "`n" | Select-String -Pattern '^LONEMORE') -join ' / ')
Check "Last session's temperatures get This week's normal / warm / hot words, hot when the card slowed itself down (10/28: 'up to 72 °C' alone)" ($r.Out -match '(?m)^SESSIONHEAT: Graphics card up to 72 °C \(normal\), processor up to 82 °C \(warm\) - from 2 measured minutes\. \| Graphics card up to 70 °C \(hot - it slowed itself down\) - from 1 measured minute\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^SESSIONHEAT') -join ' / ')
Check "Trends' subtitle follows a range change: 7 days leaves the amber line out, All brings it back (10/28)" ($r.Out -match '(?m)^TRENDRANGE: 30 days amber \| 7 days plain \| All amber \| told 3\s*$') (($r.Out -split "`n" | Select-String -Pattern '^TRENDRANGE') -join ' / ')
Check "Trends' subtitle names the amber line only when a chart shows a mark in its range (10/28)" ($r.Out -match '(?m)^TRENDMARK: with a mark shows \| none doesn''t \| before the chart doesn''t \| sub ok\s*$') (($r.Out -split "`n" | Select-String -Pattern '^TRENDMARK') -join ' / ')
Check "Trends says 'point at a chart' once in its subtitle, not under each of its 6 charts; a lone chart still says it (10/27)" ($r.Out -match '(?m)^TRENDHINT: trends chart 0 \| lone chart 1 \| subtitle says it\s*$') (($r.Out -split "`n" | Select-String -Pattern '^TRENDHINT') -join ' / ')
Check "No page subtitle joins with ' - ' (Optimizations' Choose: 'Each change Messiah makes in Windows. Keep the ones you want.', In place and Alerts too) (10/28)" ($r.Out -match '(?m)^SUBDASH: 0 of \d+ subtitles join with a dash \| Choose Each change Messiah makes in Windows\. Keep the ones you want\.\s*$') (($r.Out -split "`n" | Select-String '^SUBDASH') -join ' ')
Check "Home's headline and the quick panel join with no ' - ': 'All good, nothing needs you' (10/28)" ($r.Out -match '(?m)^HERODASH: 0 of 3 headline states join with a dash \| All good, nothing needs you\s*$') (($r.Out -split "`n" | Select-String '^HERODASH') -join ' ')
Check "Home's tile sub lines and the Claude card join with no ' - ', and send you to Optimizations, not 'Status' (10/28)" ($r.Out -match '(?m)^HOMESUBDASH: 0 of 7 join with a dash \| no Status \| Off, see Optimizations \| Ready\. Your conversation is kept, so you can pick up where you left off\s*$') (($r.Out -split "`n" | Select-String '^HOMESUBDASH') -join ' ')
Check "Settings > Tools' grey notes and the presets join with no ' - ' (10/28: 'driver before it - a restore point', 'Removes Messiah - the tray icon')" ($r.Out -match '(?m)^TOOLSDASH: 0 of 7 join with a dash \| Removes Messiah: the tray icon, the automatic maintenance and this app\. .+\s*$') (($r.Out -split "`n" | Select-String '^TOOLSDASH') -join ' ')
Check "Settings > Tools' Install USB note says what it erases and how long in full words (10/28: 'Erases it; 20-40 min.')" ($r.Out -match '(?m)^USBNOTE: plain \| It erases the stick\. Takes 20-40 minutes\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^USBNOTE') -join ' / ')
Check "a Trends chart whose newest point is over 2 days old (Start-up time: cold starts only) says 'last measured <day>' on its dates line; a fresh one doesn't (10/28)" (($r.Out -match '(?m)^STALECHART: old 2 points, now 8 s, usual 8\.5 s, last measured [A-Z][a-z]{2} \d+ \| fresh 2 points, now 42 s, usual 41 s\s*$')) (($r.Out -split "`n" | Select-String -Pattern '^STALECHART') -join ' / ')
Check "the layout audit finds a line the panel around it cuts off, though the line got all the room it asked for (Trends at 800 lost a date that way); a short or wrapping line is whole (10/28)" ($r.Out -match '(?m)^AUDITCUT: long shows 200 of \d+ px - cut by the panel around it \| short whole \| wrapped whole\s*$') (($r.Out -split "`n" | Select-String -Pattern '^AUDITCUT') -join ' / ')
Check "A chart's amber mark reads its day and why anywhere along its dashed line (5 px either side); farther off a point is read; the arrow keys reach it on the point after (10/28: only the 8 px triangle had a tooltip)" ($r.Out -match "(?m)^MARKHOVER: on the line mark \| 4 px off mark \| 30 px off point \| keys point after it \| '\w{3} \w{3} \d+: Call of Duty installed'\s*$") ([regex]::Match($r.Out, '(?m)^MARKHOVER:.*').Value)
Check "With no hint, a chart has no blank row under it: the readout takes the dates line's place when pointed at; a lone chart keeps its hint row (10/27)" ($r.Out -match '(?m)^CHARTFOOT: trends chart 3 rows, dates -> pointed readout \| lone chart 4 rows, readout -> pointed readout\s*$') (($r.Out -split "`n" | Select-String -Pattern '^CHARTFOOT') -join ' / ')
Check "Stability's note names the unanswered power-offs from before the 120-day chart (10/27: it said 3 under a chart with 2 hollow marks)" ($r.Out -match '(?m)^OLDNOTE: 3 power-offs from over 30 days ago \(1 before the chart\) were never answered, so they count as crashes here \| 1 power-off from over 30 days ago \(before the chart\) was never answered, so it counts as a crash here \| 2 power-offs from over 30 days ago were never answered, so they count as crashes here\s*$') (($r.Out -split "`n" | Select-String -Pattern '^OLDNOTE') -join ' / ')
Check "a/an before a percent goes by how it's read aloud (10/27: 'a 85% video memory budget')" ($r.Out -match '(?m)^ARTICLE: an 85% video memory budget \| a 75% video memory budget \| an 8% video memory budget \| an 11% video memory budget \| an 18% video memory budget \| an 80% video memory budget \| a 100% video memory budget\s*$') (($r.Out -split "`n" | Select-String -Pattern '^ARTICLE') -join ' / ')
Check "Home's Guarded tile's sub line doesn't repeat 'in place' (10/27: '27 in place, 1 kept' over '... - all in place')" ($r.Out -match '(?m)^GUARDSUB: nothing undone \| 2 put back \| Checked every 4 hours \| Off, see Optimizations\s*$') (($r.Out -split "`n" | Select-String -Pattern '^GUARDSUB') -join ' / ')
Check "Home's Guarded tile names what '1 kept' is (10/28: '27 in place, 1 kept' and nothing said what)" ($r.Out -match '(?m)^KEPTSUB: Xbox Game Bar kept on purpose \| 2 kept on purpose, see Optimizations \| 2 put back\s*$') (($r.Out -split "`n" | Select-String -Pattern '^KEPTSUB') -join ' / ')
Check "Settings > Tools' BIOS card keeps its steps under 'How to update it' until clicked (10/28: five steps were always open)" ($r.Out -match "(?m)^BIOSFOLD: Collapsed 2 steps, 'How to update it' \| Visible, 'Hide the steps' \| A newer BIOS fixes stability and security problems\. Messiah reminds you") (($r.Out -split "`n" | Select-String -Pattern '^BIOSFOLD') -join ' / ')
Check "Settings > Tools' BIOS card has no raw address and a readable date (10/27: a long maker's address was cut off; one line per step, or step 5 folded away)" ($r.Out -match '(?m)^BIOSCARD: ASUS ROG STRIX B650 - BIOS 3602 from Aug 1, 2026 \| no address \| Updating it: / 1\. Open its BIOS page \(the button below\) and download the newest BIOS \(newer than 3602\)\. / 2\. Unzip it\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^BIOSCARD') -join ' / ')
Check "Settings > Tools' driver and BIOS heads keep their date in one piece (10/28: '2026' was left alone on a line at 480)" ($r.Out -match '(?m)^HEADDATE: one piece \| Oct~16,~2026\s*$') (($r.Out -split "`n" | Select-String -Pattern '^HEADDATE') -join ' / ')
Check "Tools' BIOS card names the board's maker as on the box, not Windows' company name (10/28: 'ASUSTeK COMPUTER INC.')" ($r.Out -match '(?m)^BOARDMAKER: ASUS \| MSI \| Gigabyte \| ASRock \| Acme Boards \| \s*$') (($r.Out -split "`n" | Select-String -Pattern '^BOARDMAKER') -join ' / ')
Check "Tools' About card says which version this is and when it came, or when this copy was built (10/28: just 'Messiah'; a comma, not ' - ')" ($r.Out -match '(?m)^ABOUTLINE: Messiah v2\.4\.1, updated yesterday 4:00 AM \| Messiah, this copy built yesterday 4:00 AM \| Messiah\s*$') (($r.Out -split "`n" | Select-String -Pattern '^ABOUTLINE') -join ' / ')
Check "Tools' About note leaves the keys to Keyboard shortcuts, which now lists Ctrl+Alt+M (10/28: 'Tips: Ctrl+Alt+M ...; Ctrl+K ...' repeated the card)" ($r.Out -match '(?m)^ABOUTNOTE: plain \| Keeps this PC updated, tuned and checked by itself, and updates itself\. Ctrl\+/ lists the keyboard shortcuts\.\s*$') (($r.Out -split "`n" | Select-String -Pattern '^ABOUTNOTE') -join ' / ')
Check "maintenance's 'PC Setup Kit updated' line reads as Messiah in the app (10/27)" ($r.Out -match "(?m)^KITLINE: Messiah updated itself to 2026\.10\.25 \(was 2026\.10\.20\) \| Messiah updated itself to 2026\.10\.25 \| Removed temporary files \(800 MB\)\s*$") (($r.Out -split "`n" | Select-String -Pattern '^KITLINE') -join ' / ')
Check "What maintenance did: only changes - a line that just mentions an install (NVIDIA without its app, Disk Cleanup skipped, a reminder) stays out (10/28)" ($r.Out -match "(?m)^DIDLINES: did NVIDIA \| not NVIDIA \| did Driver \| not Disk Cleanup \| not Reminder \| did Steam\s*$") (($r.Out -split "`n" | Select-String -Pattern '^DIDLINES') -join ' / ')
Check "Checks: a graphics driver install reads 'Graphics driver updated to X (was Y)', not the log's 'NVIDIA: installed X' (10/28)" ($r.Out -match "(?m)^DRIVERLINE: Graphics driver updated to 566\.03 \(was 560\.94\) \| Graphics driver updated to 24\.10\.1 \| NVIDIA: 566\.03 is up to date\s*$") (($r.Out -split "`n" | Select-String -Pattern '^DRIVERLINE') -join ' / ')
Check "Settings > Tools' Your setup card doesn't say '0 chosen' (10/27)" ($r.Out -match "(?m)^SETUPLINE: none chosen yet, so this PC runs on Messiah's defaults \| 3 chosen on this PC\s*$") (($r.Out -split "`n" | Select-String -Pattern '^SETUPLINE') -join ' / ')
Check "Settings > Tools' Your setup note explains the presets in the buttons' order, in plain sentences (10/27: note Recommended first, buttons the other way; 10/28: a semicolon, two colons in a row)" (($r.Out -match "(?m)^PRESETS: Recommended, Everything for gaming \| Recommended: Messiah's defaults\. Your own Windows choices stay\. / Everything for gaming: Every game switch on\. .+ and fans\.\s*$") -and ($r.Out -notmatch '(?m)^PRESETS: .*Game Mode') -and ($r.Out -notmatch '(?m)^PRESETS: [^|\r\n]*\|[^\r\n]*(;|: [^/\r\n]*: )')) (($r.Out -split "`n" | Select-String -Pattern '^PRESETS') -join ' / ')
Check "Home's Optimizations tile counts a kept-on-purpose row apart too (10/27: '28 of 28 in place' with a kept row)" ($r.Out -match '(?m)^KEPTTILE: 2 in place, 1 kept \| 2 of 2 in place\s*$') (($r.Out -split "`n" | Select-String -Pattern '^KEPTTILE') -join ' / ')
Check "the checks' rows build their history pattern once and keep it (27 new Regexes per read before - ~5 ms, 10/27)" ($r.Out -match '(?m)^HISTRX: [1-9]\d* history patterns kept, a second read built 0\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^HISTRX:' }) -join '')
$fold = @($r.Out -split "`r?`n" | Where-Object { $_ -match '^FOLDED: ' })
Check "grey lines over 200 characters are listed with their length (FOLDED); the fixed ones only a little over - Settings' and Performance's - were shortened to fit two lines (10/27)" (-not ($fold | Where-Object { $_ -notmatch '^FOLDED: \S+: \d{3,} \| ' -or $_ -match '^FOLDED: (Settings/\S+|Activity/Performance): 2[0-4]\d \| ' })) ($fold -join ' / ')
Check 'kit-options.txt is read once per change, not once per ask (PlainNames asked for every setting name - ~10 ms of the checks, 10/26), with the same answers as before' ($r.Out -match '(?m)^OPTCACHE: 300 asks, 0 file reads \| (\d+) of \1 keys as before\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^OPTCACHE:' }) -join '')
$sets = @($r.Out -split "`r?`n" | Where-Object { $_ -match '^\s+SETTINGS: ' })
Check 'Settings > General: each switch on a card of its own with its icon, in groups (Windows 11 settings cards, 10/26)' ($sets.Count -ge 5 -and ($sets -join ' ') -match 'Open Messiah when I log in \+icon \+switch \| Show alerts in the corner \+icon \+switch' -and ($sets -join ' ') -match 'Watch the fans \+icon \+switch' -and -not @($sets -replace '^\s+SETTINGS: ' -split ' \| ' | Where-Object { $_ -notmatch ' \+icon \+switch$' })) ($sets -join ' / ')
Check 'Stability, memory test with no result yet: one short line, not folded into "..." (10/26: it was cut at every width), whole sentences with no dash (10/28: a dash at a line end read like a cut-off)' ($r.Out -match 'CARD: Memory test\s+(No results yet\. The nightly test runs by itself[^\r\n]*)' -and $Matches[1].Length -le 200 -and $Matches[1] -notmatch ' - ') (($r.Out -split "`n" | Select-String -Pattern 'CARD: Memory test' -Context 0, 1) -join ' / ')
Check 'Home: all good, no report yet'($r.Out -match 'All good, nothing needs you' -and $r.Out -match 'No report yet') ''
Check 'every button, switch, link and field has a name a screen reader can say (the window''s own parts and every page)' ($r.Out -notmatch '(?m)^A11Y:') (($r.Out -split "`r?`n" | Where-Object { $_ -match '^A11Y:' }) -join ' | ')
Check 'the chat: replies, links, attachments, edit, find and the model picker work' ($r.Out -match 'CHAT: reply=RichTextBox' -and $r.Out -match 'CHAT FIND: found=3' -and $r.Out -match 'CHAT EDIT: .*editing=True' -and $r.Out -match 'CHAT MODE: default=opus/medium chosen=sonnet/high junk=opus/medium button=\[Opus medium\]' -and $r.Out -match 'CHAT FIND: .*marked=3 leftover=0') ''
Check 'the chat: [words](address) links and tables show as such; a sign-in that ran out is recognized' ($r.Out -match 'CHAT MD: links=\[the page>Open https://example.com/p\] table=2x2 blocks=3' -and $r.Out -match 'CHAT AUTH: login=True expired=True other=False') (($r.Out -split "`n" | Where-Object { $_ -match 'CHAT (MD|AUTH)' }) -join ' / ')
Check 'files dropped from Explorer onto the window with admin rights (the older drop way Windows lets through): attached, the chat opened for them' ($r.Out -match 'CHAT DROP: read=2 attached=2 chat=Visible') ''
Check 'Claude''s steps in a row fold into one line ("3 steps - ...") that opens to list them; a reply starts a new fold' ($r.Out -match 'CHAT STEPS: groups=2 head=\[3 steps - Running health-check\.ps1\] open=3') ''
Check 'chat tabs: a name of its own (also on the phone), back to the title when cleared; a pinned tab can''t be closed' ($r.Out -match 'CHAT TAB: named=\[My build chat\] remote=\[My build chat\] cleared=\[New chat\] pinned=True closeRefused=True unpinned=True') ''
$ram = [ordered]@{ 'not started' = 'Step 1 of 2'; 'A running' = 'Now'; 'A clean' = 'Next'; 'A crashed' = 'Only the stick in slot A Next'; 'B running' = 'Now'; 'A bad' = 'Only the stick in slot A Result'
    'both bad' = 'Only the stick in slot A Only the stick in slot B Result'; 'both clean' = 'Result'; 'back too soon' = 'Both sticks are back in, but the test isn''t finished'; 'A off by the owner' = 'Now' }
$bad = @($ram.Keys | Where-Object { $r.Out -notmatch "(?m)^RAMTEST $([regex]::Escape($_)): $([regex]::Escape($ram[$_]))\s*$" })
Check 'the RAM stick test: each stage says the right thing (a power-off by the owner is no crash)' (-not $bad) "wrong: $($bad -join ', ')"
Check 'a test writes nothing into the home folder' (-not (Get-ChildItem $H -Recurse -File)) ((Get-ChildItem $H -Recurse -File).Name -join ', ')

Section 'with data (the to-do list, a report, a guard pass, what''s new, a game running)'
$H = "$Work\data"; $C = "$H\.claude"; New-Item $C, "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"
'Turn EXPO back on in the BIOS.' | Set-Content "$C\maint-todo.txt" -Encoding UTF8
'Checked 9/27/2026 12:00 PM in 18s', '[Drivers]', 'NVIDIA: 617.14 is up to date', '[PC health]', 'WARNING: blue screen 0x109 at 9/27/2026' | Set-Content "$C\maint-report.txt"
'{"at":"' + (Get-Date).ToString('o') + '","preview":false,"cause":"Windows Update (KB5099999)","optIn":[],"keys":{"telemetry":{"same":57,"fixed":[],"blocked":0},"start-menu":{"same":4,"fixed":["Start_TrackDocs"],"blocked":0}}}' | Set-Content "$C\tweak-status.json"
'{"version":"v2026.10.12","date":"' + (Get-Date).ToString('o') + '","points":["Status tab: every optimization at a glance"],"url":"https://github.com/x/y/releases/tag/v2026.10.12"}' | Set-Content "$C\whats-new.json"
$r = Run-App $H @{ PCKIT_GAME_TEST = 'Test Game'; PCKIT_REPORT_TEST = '1' }
Check 'no page fails' ($r.Code -eq 0 -and -not (Errs $r)) (Errs $r)
Check 'Home leads with what needs the owner' ($r.Out -match '1 thing needs you' -and $r.Out -match 'Turn EXPO back on in the BIOS\.') ''
Check 'Home while a game runs: maintenance waits' ($r.Out -match 'CARD: Playing Test Game') ''
Check 'Home after an update: what''s new' ($r.Out -match "CARD: What's new in Messiah v2026\.10\.12") ''
Check 'Status: what was put back, and why' ($r.Out -match 'Something had changed it: Recent files in Start - after Windows Update \(KB5099999\)') ''
$fl = ($r.Out -split "`r?`n" | Where-Object { $_ -match '^\s*FILTERS: ' }) -join ''
Check 'Optimizations after a check: no Not checked filter' ($fl -match 'Put back\s+[1-9]' -and $fl -notmatch 'Not checked') $fl
Check 'the help report: status, what needs the owner, the last check - no PC or user name' ($r.Out -match 'REPORT: Messiah report - ' -and $r.Out -match 'NEEDS THE OWNER' -and $r.Out -match 'LAST CHECK:' -and $r.Out -notmatch [regex]::Escape($env:COMPUTERNAME) -and $r.Out -notmatch [regex]::Escape($H)) ''
'{"verifier":"2026-10-04"}' | Set-Content "$C\diag-state.json"
$r = Run-App $H @{ PCKIT_DIAG_TEST = (((1..18) | ForEach-Object { "d$_.sys" }) -join ' ') + '|' }
Check 'a crash-hunting mode left on (Driver Verifier): amber, since when, with its off button' ($r.Out -match 'Driver Verifier \(18 drivers\) on / On for \d+ days \(since Oct 4\)' -and $r.Out -match '\[Turn off Driver Verifier\]') ''
$r = Run-App $H @{} @('--page', 'Welcome')
Check 'after a new install: the Welcome tab first' ($r.Out -match '(?m)^NAV: Welcome \| Home \| Games \| Health \| Optimizations \| Settings\s*$') ''
'claude=on' | Set-Content "$C\kit-options.txt"
$r = Run-App $H
Check 'with Claude: the Claude card with Open chat' ($r.Code -eq 0 -and $r.Out -match 'CARD: Claude' -and $r.Out -match 'Open chat' -and -not (Errs $r)) (Errs $r)

Section 'Games > Performance: each game''s last minute second by second, and what an update did to it'
$H = "$Work\perf"; $C = "$H\.claude"; New-Item $C, "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"
$now = Get-Date; $rows = @(foreach ($i in 0..5) { [ordered]@{ date = $now.AddDays(-12 + $i * 2).ToString('o'); game = 'TestGame'; fps = 58 + $i; low1 = 47 + $i; frames = 3500; stutters = 2; driver = $(if ($i -lt 3) { '1.0' } else { '2.0' }); build = '26200.1'; ram = $(if ($i -lt 3) { '4800 MT/s' } else { '6000 MT/s' }) } })
$rows[-1].perSec = @(1..60 | ForEach-Object { if ($_ -eq 20) { 38 } else { 60 } }); $rows[-1].worstMs = @(1..60 | ForEach-Object { if ($_ -eq 20) { 72.5 } else { 18 } })
ConvertTo-Json -InputObject $rows -Depth 4 | Set-Content "$C\perf-history.json"
$r = Run-App $H
Check 'the page builds' ($r.Out -match '(?m)^PAGE: Activity/Performance' -and -not (Errs $r)) (Errs $r)
Check 'the game''s last minute, second by second' ($r.Out -match 'CHART: The last minute, second by second \| 60 seconds, typical 60 fps') ''
Check 'a driver update: the sessions before and after, side by side, with a plain verdict' ($r.Out -match 'TestGame - Graphics driver 1\.0 -> 2\.0: better - 59 -> 62 fps \(\+5%\), 1% low 48 -> 51 \(\+6%\)') ''
$H2 = "$Work\perf0"; New-Item "$H2\.claude", "$H2\Documents" -ItemType Directory -Force | Out-Null
Check 'EXPO turned on (RAM 4800 -> 6000): its own verdict' ($r.Out -match 'TestGame - RAM speed 4800 MT/s -> 6000 MT/s: better') ''
Check 'nothing measured yet: says how it gets measured' ((Run-App $H2).Out -match 'CARD: Nothing measured yet') ''
$H3 = "$Work\perf1"; New-Item "$H3\.claude", "$H3\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$H3\.claude\kit-options.txt"
$other = [ordered]@{ date = $now.AddDays(-5).ToString('o'); game = 'OtherGame'; fps = 140; low1 = 100; frames = 8000; stutters = 0 }
ConvertTo-Json -InputObject (@($rows | ForEach-Object { $o = [ordered]@{}; foreach ($k in $_.Keys) { if ($k -notin 'perSec', 'worstMs') { $o[$k] = $_[$k] } }; $o }) + $other) -Depth 4 | Set-Content "$H3\.claude\perf-history.json"
$r3 = Run-App $H3
$sn = @($r3.Out -split "`n" | Select-String -Pattern 'second-by-second view shows' | Where-Object { $_.Line -notmatch '^SECNOTE:' })
Check "no second-by-second view in two games' last sessions: the note shows once, not under each game card, and dates like the rest of the page - not '10/21' (10/28)" ($r3.Out -match 'CARD: OtherGame' -and $sn.Count -eq 1 -and $r3.Out -notmatch 'before 10/21') (($r3.Out -split "`n" | Select-String -Pattern 'second-by-second|CARD: (Test|Other)Game') -join ' / ')
Section 'Games > Performance: a setting tried both ways, a driver on test, heat and wear (10/21)'
$H = "$Work\tune"; $C = "$H\.claude"; New-Item $C, "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"; $now = Get-Date
$rows = @(foreach ($i in 0..5) { [ordered]@{ date = $now.AddHours(-12 + $i).ToString('o'); game = 'cod'; fps = 200; low1 = 150; frames = 12000; stutters = 2; driver = '2.0'; gpuTemp = 70 + $i; gpuFan = 55; gpuPower = 290; cpuLimit = 100; cpuPerf = 112; tune = $(if ($i -lt 3) { 'vram:a' } else { 'vram:b' }) } })
$rows[-1].gpuBusy = 72; $rows[-1].latency = 11.4; $rows[-1].presentMode = 'Composed: Flip'
ConvertTo-Json -InputObject $rows -Depth 4 | Set-Content "$C\perf-history.json"
@{ active = @{ id = 'vram'; game = 'cod'; label = 'the video memory budget'; a = '0.850000'; b = '0.750000'; arm = 'b'; started = $now.AddDays(-1).ToString('o') }
   done = @(@{ id = 'reflex'; label = 'Reflex Boost'; a = 'Enabled + boost'; b = 'Enabled'; kept = 'Enabled'; why = 'faster'; at = $now.AddDays(-2).ToString('o'); aFps = 200; bFps = 204; aLow = 150; bLow = 165; aLatency = 12.5; bLatency = 10.9 },
            @{ id = 'workers'; label = 'the renderer thread count'; a = '9'; b = '8'; kept = '9'; why = 'the graphics driver reset during the test'; at = $now.AddDays(-3).ToString('o') }) } | ConvertTo-Json -Depth 4 | Set-Content "$C\game-tune.json"
@{ trial = @{ driver = '2.0'; from = '1.0'; since = $now.AddDays(-1).ToString('o'); verdict = $null; text = $null } } | ConvertTo-Json -Depth 3 | Set-Content "$C\gpu-state.json"
ConvertTo-Json -InputObject @(@{ date = $now.ToString('o'); ssdTemp = 49; ssdTempMax = 86; ssdWear = 3; gpuIdle = 28; gpuIdleFan = 70 }) | Set-Content "$C\health-history.json"
$r = Run-App $H
Check 'the page builds' (-not (Errs $r)) (Errs $r)
Check 'the setting being tried: its name once, both values, how far along, which one is on now (10/28: the name was said three times; then a closing ''On now: 75%.'' wrapped 75% onto its own line)' ($r.Out -match 'Trying now in Call of Duty: video memory budget 85% \(as before\) against 75% \(on now\) - 6 of 8 minutes of play measured\.' -and $r.Out -notmatch 'On now:') "$(($r.Out -split "`n" | Select-String 'Trying now') -join ' | ')"
Check '... and how the test runs, in two lines - not folded (10/27: it was 289 characters)' ($r.Out -match 'Switched only while the game is closed' -and $r.Out -notmatch 'FOLDED: \S+: \d+ \| Switched only') ''
Check '... each test''s result: what was faster and by how much, what was kept' ($r.Out -match 'Reflex Boost off is faster than Reflex Boost on \(delay to the screen 12\.5 -> 10\.9 ms -13%, 1% low 150 -> 165 fps \+10%, average 200 -> 204 fps\), so Messiah uses it now' -and $r.Out -match 'the renderer thread count: stopped - the graphics driver reset during the test; 9 renderer threads kept') ''
Check 'a new driver on test: against which one, how far along, what happens if it is slower' ($r.Out -match 'CARD: Graphics driver test' -and $r.Out -match 'Driver 2\.0 \(since .+\) is on test against 1\.0: 3 of 3 minutes of play measured on it\. If your games run clearly slower on it, Messiah goes back to 1\.0 by itself\.') ''
Check 'heat and wear: the graphics card while gaming and at idle, the processor, the SSD''s hottest' ($r.Out -match 'Graphics card: up to 75 °C while gaming, fan 55%, 290 W; 28 °C at idle, fan 70%' -and $r.Out -match 'Processor: at full speed while gaming \(112% of its base speed\)' -and $r.Out -match 'SSD: 49 °C now, 86 °C at its hottest \(it slows itself down from about 80 °C - a heatsink helps\), 3% worn' -and $r.Out -match 'CHART: Graphics card while gaming \| 6 points') ''
'{"trial":{"driver":"2.0","from":"1.0","since":"' + $now.AddDays(-3).ToString('o') + '","verdict":"rolled back","text":"cod runs slower on it than on 1.0 (1% low 150 -> 128 fps) - went back to 1.0"}}' | Set-Content "$C\gpu-state.json"
$r = Run-App $H
Check 'what limits the frame rate (since 10/28 the busy % in the verdict, the advice under it), the delay to the screen, frames through the compositor (10/22)' ($r.Out -match 'paced by the processor or the game \(graphics card 72% busy\)' -and $r.Out -match 'Graphics settings won.t raise it; faster RAM \(EXPO\) and fewer background apps do' -and $r.Out -match '11\.4 ms from the game starting a frame to it on screen' -and $r.Out -match 'desktop compositor') ''
Check '... a driver that failed its test: said it was undone, and why' ($r.Out -match 'Driver 2\.0 was undone - cod runs slower on it than on 1\.0') ''
'{"trial":{"driver":"2.0","from":"1.0","since":"' + $now.AddDays(-3).ToString('o') + '","verdict":"slower","text":"cod runs slower on it"}}' | Set-Content "$C\gpu-state.json"
$r = Run-App $H
Check "... a slower driver kept: its 'Settings > Tools' opens Tools, where Go back is (10/27, Ui.Linked in LineEl)" (($r.Out -match 'Driver 2\.0 is slower - cod runs slower on it\. Settings > Tools > Go back') -and ($r.Out -match '(?m)^PAGELINKS: Activity/Performance: .*Settings > Tools > Settings/Tools')) (($r.Out -split "`n" | Select-String -Pattern '^PAGELINKS:') -join ' / ')
Check 'Settings: the switch for tuning by measuring' ($r.Out -match 'Tune my games by measuring') ''
Section 'the memory test and the processor''s temperature (10/22)'
$H = "$Work\mem"; $C = "$H\.claude"; New-Item $C, "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"; $now = Get-Date
$two = '2 stick(s), 32 GB in P0 CHANNEL A + P0 CHANNEL B'; $oneA = '1 stick(s), 16 GB in P0 CHANNEL A'
@("2026-10-05 09:54 | start | $two", "$($now.AddDays(-2).ToString('yyyy-MM-dd HH:mm')) | stress | $two | 612 passes over 17 GB in 45 min at 4800 MT/s: 0 errors",
  "$($now.AddDays(-1).ToString('yyyy-MM-dd HH:mm')) | boottest | $oneA | Windows' extended memory test at start-up: errors found") | Set-Content "$C\ram-test.log"
'{"bootArmed":"' + $now.ToString('o') + '"}' | Set-Content "$C\ram-check.json"
ConvertTo-Json -InputObject @(@{ date = $now.AddHours(-1).ToString('o'); game = 'cod'; fps = 200; low1 = 150; cpuTemp = 78.5; cpuLimit = 100; cpuPerf = 110 }) | Set-Content "$C\perf-history.json"
ConvertTo-Json -InputObject @(@{ date = $now.ToString('o'); cpuIdle = 41.2; ssdTemp = 40 }) | Set-Content "$C\health-history.json"
$r = Run-App $H
Check 'the page builds' (-not (Errs $r)) (Errs $r)
Check 'Stability: the memory test card - each result, newest first, the one with errors flagged' ($r.Out -match 'CARD: Memory test' -and $r.Out -match 'Deep test at start-up - Windows'' extended memory test at start-up: errors found \(one stick, 16 GB in P0 CHANNEL A\)' -and $r.Out -match 'Nightly test - 612 passes over 17 GB in 45 min at 4800 MT/s: 0 errors' -and $r.Out -match 'Errors mean faulty memory') ''
Check '... the deep test set for the next start-up: said, with how to start it and a way to cancel' ($r.Out -match 'The deep test is set for the next start-up: restart the PC yourself' -and $r.Out -match 'BUTTONS: [^\r\n]*Cancel the deep test') ''
Check 'the stick test counts a memory test with errors like a crash for that stick' ($r.Out -match '(?m)^RAMTEST A memory test errors: Only the stick in slot A Next') ''
Check 'Heat and wear: the processor''s temperature while gaming and at idle' ($r.Out -match 'Processor: up to 78\.5 °C while gaming; 41\.2 °C at idle; at full speed while gaming \(110% of its base speed\)') ''
Check 'games by their names, not their programs'' ("cod" -> Call of Duty)' ($r.Out -match '(?m)^CARD: Call of Duty\s*$' -and $r.Out -notmatch '(?m)^CARD: cod\s*$') ''
'{"ram-stick-test":"' + $now.ToString('o') + '"}' | Set-Content "$C\maint-state.json"; 'Turn EXPO back on in the BIOS - OC Tweaker > DRAM Profile > EXPO1 > F10.' | Set-Content "$C\maint-todo.txt"
$r2 = Run-App $H
Check 'the RAM stick test running: a to-do that turns EXPO on says to wait for it (the test needs EXPO off)' ($r2.Out -match 'CARD: RAM stick test' -and $r2.Out -match 'Wait with this until the RAM stick test is done') ''
Check 'Settings: the switches for the processor''s temperature and the nightly memory test' ($r.Out -match 'Measure the processor''s temperature' -and $r.Out -match 'Test the memory at night') ''
Check "... the temperature switch's one line says what it shows, the driver's names under More (10/28: its line was 'a small signed driver (PawnIO, open source - the one ...')" ($r.Out -match '(?m)^\s*Shows how hot the processor runs while you play and at idle \(Games > Performance: Heat and wear\)\.\s*$' -and $r.Out -notmatch 'PawnIO, open source -') (($r.Out -split "`n" | Select-String 'processor runs') -join ' / ')
Check "... Keep my game settings' one line says what it does (10/28: was '... recommended ones - your tuned ones go back in by themselves ...')" ($r.Out -match '(?m)^\s*Puts your tuned Call of Duty settings back when a game update or a new graphics driver resets them to the game''s "recommended" ones\.\s*$' -and $r.Out -notmatch 'ones - your tuned ones') (($r.Out -split "`n" | Select-String 'tuned Call of Duty') -join ' / ')
Check "... Test the memory at night's one line says what it is for (10/28: was '... again and again - a flipped bit means faulty memory.')" ($r.Out -match '(?m)^\s*Checks the memory for faults while the PC sits unused \(Results: Health > Stability\)\.\s*$' -and $r.Out -notmatch 'again and again - a flipped') (($r.Out -split "`n" | Select-String 'memory for faults') -join ' / ')
Check "... Restart at night's one line says when it restarts (10/28: was '... 3:30 and 5:30 AM - only if nobody has used it ...')" ($r.Out -match '(?m)^\s*When an update waits for a restart, the PC restarts between 3:30 and 5:30 AM\.\s*$' -and $r.Out -notmatch '5:30 AM - only if') (($r.Out -split "`n" | Select-String '3:30 and 5:30') -join ' / ')
Section 'Home: "Since you last looked" - what happened while the window was closed'
$H = "$Work\since"; $C = "$H\.claude"; New-Item "$C\maint-history", "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"; $now = Get-Date
'Checked x in 20s', '[Periodic]', 'Updated app: Vendor.Tool', 'Tweaks: all still applied' | Set-Content "$C\maint-history\report-$($now.AddHours(-2).ToString('yyyyMMdd-HHmmss')).txt"
'Checked y in 20s', 'Updated app: Ancient.Thing' | Set-Content "$C\maint-history\report-20261001-090000.txt"; (Get-Item "$C\maint-history\report-20261001-090000.txt").LastWriteTime = $now.AddDays(-20)
@{ events = @(@{ key = $now.AddHours(-3).ToString('s'); at = $now.AddHours(-3).ToString('s'); kind = 'bsod'; code = '0x109' }, @{ key = $now.AddDays(-200).ToString('s'); at = $now.AddDays(-200).ToString('s'); kind = 'off'; code = ''; answer = '' }, @{ key = $now.AddDays(-60).ToString('s'); at = $now.AddDays(-60).ToString('s'); kind = 'off'; code = ''; answer = '' }); changes = @(@{ at = $now.AddHours(-2).ToString('s'); what = 'Graphics driver'; from = '617.42'; to = '618.10' }) } | ConvertTo-Json -Depth 4 | Set-Content "$C\power-log.json"
$r = Run-App $H @{ PCKIT_SINCE_TEST = $now.AddDays(-1).ToString('s') }
$card = [regex]::Match($r.Out, '(?s)CARD: Since you last looked.*?(?=TILE:|CARD:(?! Since))').Value
Check 'the checks since then and what they changed (not older ones)' ($card -match '1 check ran: Updated app: Tool' -and $card -notmatch 'Vendor\.Tool|Ancient') $card
Check '... a blue screen, a driver change' ($r.Out -match 'A blue screen [^\r\n]*\(0x109\)' -and $r.Out -match 'Graphics driver: 617\.42 -> 618\.10') ''
Check 'Stability: power-offs over 30 days old never answered - "not answered" (no "yet"), one click to say they were the owner''s; Home doesn''t ask about them (10/26)' ($r.Out -match 'Went off without a blue screen \(not answered\)' -and $r.Out -notmatch 'not answered yet' -and $r.Out -match '2 power-offs from over 30 days ago were never answered' -and $r.Out -match '\b1 not answered' -and $r.Out -notmatch '0 by you|0 froze' -and $r.Out -match 'BUTTONS: [^\r\n]*I turned those 2 off' -and $r.Out -notmatch 'did you turn it off') ''
Check "Stability's tiles open the list of events under them, What happened - one with nothing to count doesn't (10/27: they did nothing)" (($r.Out -match '(?m)^\s+TILE: Days since the last crash: \d+ / [^\r\n]+\r?\n\s+GO: Activity/Stability#What happened \(Open Health > Stability\)\s*$') -and ($r.Out -match '(?m)^\s+TILE: Power-offs, 120 days: [1-9]\d* / [^\r\n]+\r?\n\s+GO: Activity/Stability#What happened ') -and ($r.Out -notmatch '(?m)^\s+TILE: (Blue screens|Power-offs)[^\r\n]+: 0 / [^\r\n]+\r?\n\s+GO: ') -and ($r.Out -match 'CARD: What happened')) (($r.Out -split "`n" | Select-String -Pattern 'TILE: (Days since|Blue screens|Power-offs)' -Context 0, 1) -join ' / ')
Check "Stability's tiles count the same 120 days as the chart and What happened (10/28: the tiles said 90 - '1 not answered' but 2 hollow marks)" (($r.Out -match '(?m)^\s+TILE: Blue screens, 120 days: ') -and ($r.Out -match '(?m)^\s+TILE: Power-offs, 120 days: ') -and ($r.Out -match 'CARD: Last 120 days') -and ($r.Out -notmatch 'TILE: [^\r\n]*90 days')) (($r.Out -split "`n" | Select-String -Pattern 'TILE: (Blue|Power)|CARD: Last') -join ' / ')
Check 'never closed before (no time recorded): no card' ((Run-App $H).Out -notmatch 'Since you last looked') ''
Section 'Health > Stability: "Copy a crash report" - the last crash, ready for a forum post (10/26)'
$H = "$Work\crashrep"; $C = "$H\.claude"; New-Item "$C\maint-history", "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"; $now = Get-Date
function Ev($days, $kind, $code, $answer) { $t = $now.AddDays(-$days).ToString('s'); @{ key = $t; at = $t; kind = $kind; code = $code; answer = $answer } }
function Chg($days, $what, $from, $to) { @{ at = $now.AddDays(-$days).ToString('s'); what = $what; from = $from; to = $to } }
@{ events = @((Ev 2 'bsod' '0x124' ''), (Ev 5 'bsod' '0x109' ''), (Ev 10 'off' '' 'froze'), (Ev 3 'off' '' 'me'))
   changes = @((Chg 4 'BIOS' '4.40' '4.43'), (Chg 20 'Graphics driver' '600.01' '610.02'), (Chg 1 'Graphics driver' '610.02' '618.10')) } | ConvertTo-Json -Depth 4 | Set-Content "$C\power-log.json"
"Checked x in 20s", "WARNING: crash dump $($now.AddDays(-2).ToString('MMddyy'))-11500-01.dmp - code 124 | blamed: Unknown_Image (Unknown_Module) | process: System | bucket: MEMORY_CORRUPTION_ONE_BIT" | Set-Content "$C\maint-history\report-$($now.AddDays(-1).ToString('yyyyMMdd-HHmmss')).txt"
"$($now.AddDays(-1).ToString('yyyy-MM-dd HH:mm:ss')) | stress | 2 stick(s), 32 GB | 3 passes: 0 errors" | Set-Content "$C\ram-test.log"
$r = Run-App $H; $cr = ($r.Out -split "`r?`n" | Where-Object { $_ -match '^CRASHREPORT: ' }) -join ''
Check 'the last blue screen with its code''s name and what its dump''s analysis said' ($cr -match "LAST CRASH: blue screen 0x124 WHEA_UNCORRECTABLE_ERROR on $([regex]::Escape($now.AddDays(-2).ToString('yyyy-MM-dd'))) [\d:]+ / +Crash dump analysis: no driver named \(Unknown_Image\); process System; bucket MEMORY_CORRUPTION_ONE_BIT") $cr
Check '... 90 days: both blue screens by code, the power-off that froze (not the one the owner made)' ($cr -match 'LAST 90 DAYS: 2 blue screens \(0x124 WHEA_UNCORRECTABLE_ERROR, 0x109 CRITICAL_STRUCTURE_CORRUPTION\); 1 power-off without one' -and $cr -match 'went off - the owner says it froze' -and $cr -notmatch 'went off - not answered') $cr
Check '... what changed in the 14 days before it (not after it, not older)' ($cr -match 'CHANGED IN THE 14 DAYS BEFORE IT: / +\S+: BIOS 4\.40 -> 4\.43' -and $cr -notmatch '600\.01|618\.10') $cr
Check '... the memory test; codes named whatever way they''re written' ($cr -match 'MEMORY TEST: / +\S+: in Windows \(nightly\) - 3 passes: 0 errors \(2 stick\(s\), 32 GB\)' -and $cr -match '\| names: 0x109 CRITICAL_STRUCTURE_CORRUPTION, 0x124 WHEA_UNCORRECTABLE_ERROR, 0x1234\s*$') $cr
Check '... the button on Stability''s What happened card' ($r.Out -match 'BUTTONS: [^\r\n]*Copy a crash report') ''
Check '... and in Ctrl+K search once a crash is recorded, not with only the owner''s own power-offs (10/27)' ($r.Out -match '(?m)^SEARCHCRASH: Action - the last crash and what changed before it, for a forum post \| only the owner''s power-offs: none\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^SEARCHCRASH:' }) -join '')
Check '... 3 crashes: all listed, no "newest 10 of"' ($cr -notmatch 'newest 10 of') $cr
$ev = @((Ev 2 'bsod' '0x124' ''), (Ev 5 'bsod' '0x109' ''), (Ev 10 'off' '' 'froze'), (Ev 3 'off' '' 'me')) + @(20..31 | ForEach-Object { Ev $_ 'bsod' '0x109' '' })
@{ events = $ev; changes = @() } | ConvertTo-Json -Depth 4 | Set-Content "$C\power-log.json"
$cr = ((Run-App $H).Out -split "`r?`n" | Where-Object { $_ -match '^CRASHREPORT: ' }) -join ''
Check '... 15 crashes: the list says it''s cut ("newest 10 of 15") and stops at the 10th (10/26)' ($cr -match 'LAST 90 DAYS: 14 blue screens[^/]*/ +\(newest 10 of 15\) / ' -and $cr -match [regex]::Escape($now.AddDays(-26).ToString('yyyy-MM-dd')) -and $cr -notmatch [regex]::Escape($now.AddDays(-27).ToString('yyyy-MM-dd'))) $cr
Section 'Health > Checks: "What maintenance did" - a heading per day (10/26)'
$H = "$Work\days"; $C = "$H\.claude"; New-Item "$C\maint-history", "$H\Documents" -ItemType Directory -Force | Out-Null
'claude=off' | Set-Content "$C\kit-options.txt"; $t0 = (Get-Date).Date
function Report([datetime]$at, [string[]]$lines) { (@("Checked $($at.ToString('g')) in 20s") + $lines) | Set-Content "$C\maint-history\report-$($at.ToString('yyyyMMdd-HHmmss')).txt" }
Report $t0.AddHours(9) 'Updated app: Vendor.Tool', 'Updated app: Other.App', 'Removed leftover folder Old Game'
Report $t0.AddHours(9).AddMinutes(30) 'Restore point created'
Report $t0.AddDays(-1).AddHours(20) 'Driver: NVIDIA installed 560.94'
Report $t0.AddDays(-3).AddHours(8) 'Removed a', 'Removed b', 'Removed c'
Report $t0.AddDays(-20).AddHours(8) 'Removed d', 'Removed e'
$r = Run-App $H
$card = [regex]::Match($r.Out, '(?s)CARD: What maintenance did.*?(?=\r?\nCARD:|\r?\nPAGE:)').Value
$day3 = $t0.AddDays(-3).ToString('dddd, MMM d'); $d20 = $t0.AddDays(-20); $day20 = $d20.ToString($(if ($d20.Year -eq $t0.Year) { 'dddd, MMM d' } else { 'dddd, MMM d, yyyy' }))
Check 'each day once with its lines; the newest days up to 8 lines show, the earlier ones behind "Show 1 earlier day"' (($card -match [regex]::Escape("DAYS: Today (3) | Yesterday (1) | $day3 (3) | $day20 (2)")) -and ($card -match 'BUTTONS: Show 1 earlier day')) $card
Check '... a check''s time once, beside its first line (no "today" on every line)' (($card -match '(?m)^  9:30 \S+: Restore point created') -and ($card -match '(?m)^  9:00 \S+: Updated 2 apps: Tool, App') -and ($card -match '(?m)^  Removed leftover folder Old Game') -and ($card -notmatch 'today \d')) $card
Section 'the demo profile for screenshots and --audit (tools\app\demo-profile.ps1, 10/26)'
$demo = "$Kit\..\tools\app\demo-profile.ps1"
if (-not (Test-Path $demo)) { Skip 'demo profile' 'tools\app not here (a published kit)' } else {
    $H = "$Work\demo"; & $demo -Path $H | Out-Null; $r = Run-App $H
    $fl = ($r.Out -split "`r?`n" | Where-Object { $_ -match '^\s*FILTERS: ' }) -join ''
    Check 'it reads like a PC checked for weeks: a report, the next check from the schedule, every optimization checked, no page fails' (($r.Out -notmatch 'No report yet') -and ($r.Out -match 'TILE: Next: App updates / Tomorrow') -and ($fl -notmatch 'Not checked') -and -not (Errs $r)) "$fl | $(Errs $r) | $(($r.Out -split "`n" | Select-String 'TILE: Next') -join '')"
    Check 'Performance shows the setting being tried (Call of Duty, 6 of 8 minutes) and the one already decided' (($r.Out -match 'Trying now in Call of Duty: .+ - 6 of 8 minutes of play measured') -and ($r.Out -match 'Reflex Boost .+ so Messiah uses it now')) "$(($r.Out -split "`n" | Select-String 'Trying now|Reflex') -join ' | ')"
    Check 'a minute without the graphics card''s busy share says only its heat, not "0% busy"' (($r.Out -match 'Graphics card up to \d+ °C') -and ($r.Out -notmatch '°C, 0% busy')) "$(($r.Out -split "`n" | Select-String 'Graphics card up to') -join ' | ')"
    Check 'a game recorded by its program''s name (Apex: r5apex_dx12) reads by its own name' (($r.Out -match 'Apex Legends') -and ($r.Out -notmatch 'r5apex')) "$(($r.Out -split "`n" | Select-String 'Apex|r5apex' | Select-Object -First 3) -join ' | ')"
    Check '... and a game no list knows by the title game-perf.ps1 found (Hunt: HuntGame), in Earlier games (10/27)' (($r.Out -match 'Earlier games[\s\S]{0,400}Hunt: Showdown 1896') -and ($r.Out -notmatch 'HuntGame')) "$(($r.Out -split "`n" | Select-String 'Hunt' | Select-Object -First 3) -join ' | ')"
    $tr = ($r.Out -split "`r?`n" | Where-Object { $_ -match 'CHART: (Start-up time|Free space on C:|SSD temperature|Internet ping at idle) \|' }) -join ' / '
    Check 'Health > Trends draws its charts from five weeks of checks (none still "Collecting"), C: ends at storage.json''s 997 GB (10/27)' (($tr -match 'Start-up time \| [5-9] points') -and ($tr -match 'Free space on C: \| \d{2} points, now 997 GB') -and ($tr -match 'SSD temperature \| \d{2} points') -and ($tr -match 'Internet ping at idle \| \d{2} points')) $tr
    Check '... and Free space says how far C: moved since the range''s first point, not a "usual" level it is never at; the others keep "usual" (10/27) - and the demo''s marked drop by its day (10/28)' (($tr -match 'Free space on C: \| \d+ points, now 997 GB, down \d+ GB since [A-Z][a-z]{2} \d+, most of it on [A-Z][a-z]{2} \d+ \|') -and ($tr -notmatch 'Free space on C:[^/]*usual') -and ($tr -match 'SSD temperature \| \d+ points, now [\d.]+ °C, usual')) $tr
    Check '... and the demo''s 60 GB drop 12 days ago is a mark on it (10/27)' ($tr -match 'Free space on C:[^/]*marks: 6\d GB less free') $tr
    Check 'Storage''s games put their buttons in one shared column, so the sizes line up with or without a Move button (10/27; 5 since the demo lists both NBA 2K23 copies, 10/28)' ($r.Out -match '(?m)^\s*BTNCOL: storagegames \(5 rows\)\s*$') "$(($r.Out -split "`n" | Select-String 'BTNCOL') -join ' | ')"
    Check '... and each drive says how many games are on it - "in 2 games", not "in 2" (10/27); NBA 2K23 on C: twice is one game, named (10/28)' (($r.Out -match 'Games: 495 GB in 2 games \(NBA 2K23 twice\)') -and ($r.Out -notmatch '(?m)Games: [^\r\n]* in \d+\s*$')) "$(($r.Out -split "`n" | Select-String 'Games: ') -join ' | ')"
    $H = "$Work\demo-full";& $demo -Path $H -Full | Out-Null; $r = Run-App $H
