    Check '-Full: C: nearly full, so Storage shows the big game''s "Moving it ... frees" note' (($fr -match '^FREES: Call of Duty: Moving it to D: frees 13% of C:') -and -not (Errs $r)) "$fr | $(Errs $r)"
}

