Check "Settings' switches: 'Results: Games > Performance' / 'Health > Stability' / 'Health > Alerts' open the page (10/27, Ui.Linked in SwitchRow + LineEl)" (($r.Out -match '(?m)^PAGELINKS: Settings/General: .*Games > Performance > Activity/Performance') -and ($r.Out -match '(?m)^PAGELINKS: Settings/General: .*Health > Stability > Activity/Stability') -and ($r.Out -match '(?m)^PAGELINKS: Settings/General: .*Health > Alerts > Activity/Alerts')) (($r.Out -split "`n" | Select-String -Pattern '^PAGELINKS:') -join ' / ')
Check "Settings' 'Show technical names' names Optimizations > In place (a link), not a 'Status row' (10/28)" (($r.Out -match '(?m)^PAGELINKS: Settings/General: .*Optimizations > In place > Status') -and ($r.Out -notmatch "a Status row's details")) (($r.Out -split "`n" | Select-String -Pattern '^PAGELINKS: Settings/General') -join ' / ')
Check 'Health > Trends: the PC''s own vitals only - the games'' charts are on Games > Performance (10/25: they were in both places)' ($r.Out -match 'CHART: Internet ping at idle \|' -and $r.Out -notmatch 'CHART: Frame rate - Call of Duty') ''
