Check "... and with no cpu-temp.ps1 it isn't started (was PowerShell's '-File ... does not exist' error, 10/27)" ($r.Out -match ("(?m)^QUICKTEMP: cpu-temp\.ps1 " + $(if (Test-Path (Join-Path $H '.claude\cpu-temp.ps1')) { 'there' } else { 'missing - not started' }))) ''
