Check 'a session: its connection, and network or PC (the PC ran fine: the connection)' ($r.Out -match 'Connection while playing: ping 14 ms \(9 at idle\), 5% of packets lost, 4 lag spikes \(past the router - the modem or the provider\)\. The PC ran fine - if this match felt laggy, it was the connection, not the PC\.') ''
Check 'Performance, Connection: in-game vs idle, the bad minutes, what would help (Wi-Fi, loss past the router), the DNS' ($r.Out -match 'CARD: Connection\s+While you play: ping 14 ms \(9 at idle\), 1 of 2 measured minutes with lag' -and $r.Out -match 'You play on Wi-Fi - a network cable' -and $r.Out -match 'Packets are lost past the router' -and $r.Out -match 'DNS, 1\.1\.1\.1\): 11 ms, the fastest public one 21 ms') ''
Check 'Storage: the drives, the games (a Steam game can move to the drive with room), the leftovers (a folder: the size right-aligned, why as a line under it - 10/28), installed twice' ($r.Out -match 'CARD: Drives[\s\S]{0,80}Local Disk \(C:\) +- +SSD, Windows[\s\S]{0,200}Games \(D:\) +- +hard drive' -and $r.Out -match 'BUTTONS: .*Move to D:' -and $r.Out -match '1 leftover of uninstalled games - 1\.5 GB' -and $r.Out -match 'Clean them up' -and $r.Out -match '3\.0 GB\s+OldGame\s+No installed game uses it\. It may hold old saves\.' -and $r.Out -notmatch 'OldGame - no installed' -and $r.Out -match 'CARD: Installed twice\s+NBA 2K23') ''
Check '... a leftover and each copy of a game installed twice open their folder the same way (10/26)' ($r.Out -match 'BUTTONS: Open folder - C:\\Steam\\steamapps\\common\\OldGame \| To the Recycle Bin \| Clean them up' -and $r.Out -match '(?m)^\s*BUTTONS: Open folder - C:\\x \| Open folder - C:\\Games\\NBA 2K23\s*$' -and $r.Out -notmatch '\bShow \|') (($r.Out -split "`n" | Where-Object { $_ -match 'Open folder' }) -join ' / ')
Check '... each copy says what starts it: Steam''s own (in its library), a Steam shortcut into a folder copy, else nothing - and the line under the card says the one nothing starts is usually the spare (10/26)' (($r.Out -match '(?m)^STARTS: NBA 2K23: Steam''s own copy - in its library / Your Steam shortcut starts this one\s*$') -and ($r.Out -match '(?m)^STARTSCASES: No launcher or shortcut starts this one \| Your Steam shortcut starts this one \| No launcher or shortcut starts this one \| Its own installer put it here - in Windows'' Installed apps\s*$') -and ($r.Out -match '•  Your Steam shortcut starts this one') -and ($r.Out -match 'the copy nothing starts is usually the spare')) (($r.Out -split "`n" | Where-Object { $_ -match '^STARTS' }) -join ' / ')
Check '... a game row with no Move button says why (Epic, a shortcut, its own installer, a folder, no room) - not with a button or one drive (10/28)' ($r.Out -match '(?m)^WHYNOMOVE: steam none \| too big No \| epic Epic \| shortcut Not \| own It \| folder Only \| one drive none\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^WHYNOMOVE' }) -join ' / ')
Check '... a long game name trims and keeps its store and drive beside it on one line; a short name is whole (10/28)' ($r.Out -match '(?m)^NAMETAG: long one line fits tag whole trimmed \| short one line fits tag whole whole\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^NAMETAG' }) -join ' / ')
Check '... a folder game a Steam shortcut starts says "Steam shortcut" on its row, Steam games stay Steam (10/26)' (($r.Out -match '(?m)^STORES: Call of Duty: Steam \| NBA 2K23: Steam shortcut \| Apex Legends: Steam\s*$') -and ($r.Out -match 'Steam shortcut - C:')) (($r.Out -split "`n" | Where-Object { $_ -match '^STORES' }) -join ' / ')
Check '... a drive''s games line counts a game installed twice on it once and names it: "Games: 495 GB in 2 games (NBA 2K23 twice)" (10/28)' ($r.Out -match '(?m)^GAMESLINE: Games: 495 GB in 2 games \(NBA 2K23 twice\) \| Games: 377 GB in 2 games \| Games: 495 GB in 3 games\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^GAMESLINE' }) -join ' / ')
Check '... each game opens its folder (the path in its tooltip); sorted biggest first, A to Z or by drive (C first) - by drive only with games on 2+ drives (10/26)' (($r.Out -match 'BUTTONS: Open folder - C:\\Games\\NBA 2K23 \| Open folder - D:\\SteamLibrary\\steamapps\\common\\Apex Legends \| Move to D: \| Open folder - C:\\Steam\\steamapps\\common\\COD') -and ($r.Out -match '(?m)^SORT: size: NBA 2K23, Apex Legends, Call of Duty \| name: Apex Legends, Call of Duty, NBA 2K23 \| drive: NBA 2K23, Call of Duty, Apex Legends\s*$') -and ($r.Out -match 'CARD: Games\s+132 GB\s+NBA 2K23[\s\S]{0,200}Apex Legends[\s\S]{0,200}Call of Duty')) (($r.Out -split "`n" | Where-Object { $_ -match '^SORT:|Open folder' }) -join ' / ')
Check '... a big game on a nearly full drive says what moving it frees, or that the drive is nearly full - not on a roomy drive (10/27)' ($r.Out -match '(?m)^FREES: Call of Duty: - \| NBA 2K23: 13% of a nearly full C: \| Apex Legends: - \| CASES: full C: \+ D: Moving it to D: frees 25% of C: \| roomy C: - \| D: too small 25% of a nearly full C:\s*$')(($r.Out -split "`n" | Where-Object { $_ -match '^FREES:' }) -join ' / ')
Check '... each game a thin bar: its share of its own drive (132 of 1000 GB, 80 of 2000), biggest first (10/26)' ($r.Out -match '(?m)^SHARE: NBA 2K23 13%, Apex Legends 4%, Call of Duty 6%\s*$') (($r.Out -split "`n" | Where-Object { $_ -match '^SHARE:' }) -join ' / ')

Section 'the layout audit (--audit): every page, the smallest window to a 2560 px screen, chat closed and open, dark and light (10/25)'
# (CLIP: words or a button cut off; OVERLAP: buttons on top of each other; OUTSIDE: past the window's edge; CONTRAST:
# words too faint for WCAG AA - 4.5:1, large text and icons 3:1 (10/26). The pages
# with the most in them: the data home of the Performance tests and a new install - and that install with Claude on,
# so the chat box and the top bar's Ask Claude are audited too (10/27: the chat's placeholder was cut off by 1 px at
# every chat width, and at 480 the Welcome tab pushed Settings over Search - claude=off never showed either).)
foreach ($hm in @("$Work\tune", "$Work\new", "$Work\new+ai")) {
    $home2 = $hm -replace '\+ai$'; $ai = $hm -ne $home2
    $ko = "$home2\.claude\kit-options.txt"; $was = if (Test-Path $ko) { Get-Content $ko -Raw }
    if ($ai) { 'claude=on' | Set-Content $ko }
    foreach ($th in 'dark', 'light') {
        $r = Run-App $home2 @{ PCKIT_THEME = $th } @('--audit', "`"$Work\audit-$th`"", '--noshots')
        $f = @($r.Out -split "`r?`n" | Where-Object { $_ -match '^AUDIT (?!DONE)' })
        Check "$(Split-Path $hm -Leaf), $($th): nothing cut off, overlapping, past the edge or too faint to read" ($r.Out -match 'AUDIT DONE.*contrast of [1-9]\d* texts checked' -and -not $f) ((@($f | Select-Object -First 8) + @($r.Err.Trim()) | Where-Object { $_ }) -join ' | ')
        # (the chat is checked with a long draft past the box's MaxHeight and three files going with it - alone when narrow,
        # beside Home from 900 px - 10/27)
        if ($ai) { Check "new+ai, $($th): the chat box is audited with a draft and files, narrow and beside a page" ($r.Out -match 'AUDIT DONE.*chat with a draft and files: [1-9]\d* width\(s\), [1-9]\d* beside a page') ($r.Out -split "`r?`n" | Where-Object { $_ -match 'AUDIT DONE' } | Select-Object -First 1) }
    }
    if ($ai) { if ($null -ne $was) { Set-Content $ko $was -NoNewline } else { Remove-Item $ko -Force } }
}
# the first-start tour's card: checked on its own (over Home), not left over every page - and the audit doesn't mark it seen (10/26)
$opts = "$Work\new\.claude\kit-options.txt"
Check 'the audit checks the tour on its own and leaves it unseen' ($r.Out -match 'AUDIT DONE.*pages: .*\bTour\b' -and -not ((Test-Path $opts) -and (Select-String -Path $opts -Pattern '^\s*tour\s*=' -Quiet))) ($r.Out -split "`r?`n" | Where-Object { $_ -match 'AUDIT DONE' } | Select-Object -First 1)
Finish
